<script setup>
import { computed, onMounted, ref } from 'vue';
import PortalLayout from '../layouts/PortalLayout.vue';
import api from '../services/api';
import { useAuthStore } from '../stores/auth';

const auth=useAuthStore(),admin=computed(()=>auth.user?.role==='ADMIN');
const rows=ref([]),detail=ref(null),total=ref(0),page=ref(1),loading=ref(false),saving=ref(false),error=ref(''),notice=ref('');
const filters=ref({search:'',status:'',category:'',requester:'',date:''});
const blank=()=>({title:'',category:'SUPPLIES',description:'',quantity:'1',unit:'piece',purpose:'',neededBy:'',estimatedUnitCost:'',status:'DRAFT',attachment:null});
const form=ref(blank()),editing=ref(null);
const categories=[['SUPPLIES','Supplies'],['EQUIPMENT','Equipment'],['BOOKS','Books'],['LEARNING_RESOURCES','Learning resources']];
const statuses=['DRAFT','SUBMITTED','APPROVED','REJECTED','ORDERED','RECEIVED','CANCELLED'];
const totalEstimate=computed(()=>form.value.estimatedUnitCost?Number(form.value.quantity||0)*Number(form.value.estimatedUnitCost):null);
async function load(){loading.value=true;error.value='';try{const result=await api.get('/acquisitions',{params:{...filters.value,page:page.value}});rows.value=result.data.data.rows;total.value=result.data.data.total;}catch(e){error.value=e.response?.data?.message||'Could not load resource requests.';}finally{loading.value=false;}}
async function open(item){error.value='';try{detail.value=(await api.get(`/acquisitions/${item.id}`)).data.data;}catch(e){error.value=e.response?.data?.message||'Could not load request details.';}}
function clear(){editing.value=null;form.value=blank();}
function edit(item){editing.value=item.id;form.value={...blank(),...item,neededBy:item.neededBy?.slice(0,10)||'',estimatedUnitCost:item.estimatedUnitCost??'',attachment:null};document.getElementById('acquisition-form')?.scrollIntoView({behavior:'smooth',block:'start'});}
async function save(){if(saving.value)return;saving.value=true;error.value='';notice.value='';try{
  const body=new FormData();for(const key of ['title','category','description','quantity','unit','purpose','neededBy','estimatedUnitCost'])body.set(key,form.value[key]??'');
  if(!editing.value)body.set('status',form.value.status);if(form.value.attachment)body.set('attachment',form.value.attachment);
  if(editing.value)await api.patch(`/acquisitions/${editing.value}`,body);else await api.post('/acquisitions',body);
  notice.value=editing.value?'Draft updated.':'Request created.';clear();await load();
}catch(e){error.value=e.response?.data?.message||'Could not save the request.';}finally{saving.value=false;}}
function actions(item){if(item.status==='DRAFT'&&(admin.value||Number(item.requesterId)===Number(auth.user?.id)))return ['SUBMITTED','CANCELLED'];if(item.status==='SUBMITTED')return admin.value?['APPROVED','REJECTED']:Number(item.requesterId)===Number(auth.user?.id)?['CANCELLED']:[];if(admin.value&&item.status==='APPROVED')return ['ORDERED'];if(admin.value&&item.status==='ORDERED')return ['RECEIVED'];return [];}
async function advance(item,status){if(saving.value)return;let comment='';if(['REJECTED','CANCELLED'].includes(status)){comment=window.prompt(`Reason for ${status.toLowerCase()}:`)||'';if(!comment.trim())return;}else if(!window.confirm(`Move “${item.title}” to ${status.toLowerCase()}?`))return;
  saving.value=true;error.value='';try{await api.patch(`/acquisitions/${item.id}/status`,{status,comment});notice.value=`Request moved to ${status.toLowerCase()}.`;await load();if(detail.value?.id===item.id)await open(item);}catch(e){error.value=e.response?.data?.message||'Could not change request status.';}finally{saving.value=false;}}
async function download(item){try{const response=await api.get(`/acquisitions/${item.id}/attachment`,{responseType:'blob'});const url=URL.createObjectURL(response.data);const link=document.createElement('a');link.href=url;link.download=item.attachmentName||'resource-request';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}catch(e){error.value=e.response?.data?.message||'Could not download attachment.';}}
function money(value){return value==null?'—':new Intl.NumberFormat('en-PH',{style:'currency',currency:'PHP'}).format(Number(value));}
onMounted(load);
</script>
<template><PortalLayout title="Acquisitions"><div class="dashboard content-page"><div class="page-heading"><div><p class="eyebrow">DEPARTMENT RESOURCES</p><h2>Acquisitions</h2><p>Track requests for supplies, equipment, books, and learning resources. Approval does not place an order or process payment.</p></div></div>
  <p v-if="error" class="form-error" role="alert">{{error}}</p><p v-if="notice" class="success-message" role="status">{{notice}}</p>
  <section class="panel"><h2>Resource requests</h2><form class="toolbar" @submit.prevent="page=1;load()"><label>Search<input v-model="filters.search" placeholder="Title or description"/></label><label>Status<select v-model="filters.status"><option value="">All statuses</option><option v-for="status in statuses" :key="status" :value="status">{{status}}</option></select></label><label>Category<select v-model="filters.category"><option value="">All categories</option><option v-for="[value,label] in categories" :key="value" :value="value">{{label}}</option></select></label><label v-if="admin">Requester ID<input v-model="filters.requester" type="number" min="1"/></label><label>Created on<input v-model="filters.date" type="date"/></label><button class="secondary-button">Filter requests</button><button type="button" class="text-button" @click="filters={search:'',status:'',category:'',requester:'',date:''};page=1;load()">Clear filters</button></form>
    <p class="empty" role="status">{{total}} matching request{{total===1?'':'s'}}</p><p v-if="loading" class="empty">Loading requests…</p><div v-else-if="rows.length" class="record-list"><article v-for="item in rows" :key="item.id" class="record-row"><div><strong>{{item.title}}</strong><span>{{item.category.replaceAll('_',' ')}} · {{item.status}} · {{item.requesterName}}</span><small>{{item.quantity}} {{item.unit}} · Estimated total {{money(item.estimatedTotal)}} · {{new Date(item.createdAt).toLocaleDateString('en-PH')}}</small></div><div class="inline-actions"><button class="text-button" @click="open(item)">View details</button><button v-if="item.status==='DRAFT'&&(admin||Number(item.requesterId)===Number(auth.user?.id))" class="text-button" @click="edit(item)">Edit draft</button><button v-for="status in actions(item)" :key="status" class="text-button" :disabled="saving" @click="advance(item,status)">{{status.charAt(0)+status.slice(1).toLowerCase()}}</button></div></article></div><p v-else class="empty">No resource requests match these filters.</p><div class="pagination"><button :disabled="page===1" @click="page--;load()">Previous</button><span>Page {{page}} · {{total}} requests</span><button :disabled="page*20>=total" @click="page++;load()">Next</button></div></section>
  <section v-if="detail" class="panel narrow-panel" aria-label="Resource request details"><div class="panel-title"><h2>{{detail.title}}</h2><button class="text-button" @click="detail=null">Close</button></div><div class="detail-list"><div><dt>Status</dt><dd>{{detail.status}}</dd></div><div><dt>Requester</dt><dd>{{detail.requesterName}}</dd></div><div><dt>Category</dt><dd>{{detail.category.replaceAll('_',' ')}}</dd></div><div><dt>Quantity</dt><dd>{{detail.quantity}} {{detail.unit}}</dd></div><div><dt>Needed by</dt><dd>{{detail.neededBy?.slice(0,10)||'Not specified'}}</dd></div><div><dt>Estimated unit cost</dt><dd>{{money(detail.estimatedUnitCost)}}</dd></div><div><dt>Estimated total</dt><dd>{{money(detail.estimatedTotal)}}</dd></div></div><h3>Description</h3><p>{{detail.description}}</p><h3>Purpose</h3><p>{{detail.purpose}}</p><button v-if="detail.attachmentName" class="secondary-button" @click="download(detail)">Download {{detail.attachmentName}}</button><h3>Status history</h3><ol class="acquisition-history"><li v-for="(entry,index) in detail.history" :key="index"><strong>{{entry.toStatus}}</strong> by {{entry.actorName}} · {{new Date(entry.createdAt).toLocaleString('en-PH')}}<p v-if="entry.comment">{{entry.comment}}</p></li></ol></section>
  <section id="acquisition-form" class="panel narrow-panel"><h2>{{editing?'Edit draft':'New resource request'}}</h2><form class="stack-form" @submit.prevent="save"><label>Request title<input v-model="form.title" required maxlength="180"/></label><label>Category<select v-model="form.category"><option v-for="[value,label] in categories" :key="value" :value="value">{{label}}</option></select></label><label>Description<textarea v-model="form.description" required maxlength="5000"/></label><div class="form-grid"><label>Quantity<input v-model="form.quantity" type="number" min="0.01" max="99999999" step="0.01" required/></label><label>Unit<input v-model="form.unit" required maxlength="40" placeholder="piece, box, set…"/></label></div><label>Purpose<textarea v-model="form.purpose" required maxlength="3000"/></label><div class="form-grid"><label>Needed by (optional)<input v-model="form.neededBy" type="date"/></label><label>Estimated unit cost in PHP (optional)<input v-model="form.estimatedUnitCost" type="number" min="0" max="999999999" step="0.01"/></label></div><p v-if="totalEstimate!==null">Estimated total: {{money(totalEstimate)}}</p><label>Attachment (optional, PDF/PNG/JPEG, up to 5 MB)<input type="file" accept="application/pdf,image/png,image/jpeg" @change="form.attachment=$event.target.files?.[0]||null"/></label><label v-if="!editing">Initial status<select v-model="form.status"><option value="DRAFT">Save draft</option><option value="SUBMITTED">Submit for review</option></select></label><div class="inline-actions"><button class="primary" :disabled="saving">{{saving?'Saving…':editing?'Save draft':form.status==='SUBMITTED'?'Submit request':'Save draft'}}</button><button v-if="editing" type="button" class="secondary-button" @click="clear">Cancel edit</button></div></form></section>
</div></PortalLayout></template>
